class DriverOrdersDto {
  DriverOrdersDto({
    this.message,
    this.orders,
  });

  DriverOrdersDto.fromJson(dynamic json) {
    message = json['message'];
    if (json['orders'] != null) {
      orders = [];
      json['orders'].forEach((v) {
        orders?.add(Orders.fromJson(v));
      });
    }
  }

  String? message;
  List<Orders>? orders;

  Map<String, dynamic> toJson() {
    final map = <String, dynamic>{};
    map['message'] = message;

    if (orders != null) {
      map['orders'] = orders?.map((v) => v.toJson()).toList();
    }
    return map;
  }

  DriverOrdersEntities toEntity() => DriverOrdersEntities(
      message: message, orders: orders?.map((e) => e.toEntity()).toList());
}

